import Image from 'next/image'

import { Marquee } from '@/components/library/motion/Marquee'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type MarqueeGalleryItem = {
  src: string
  alt: string
  caption?: string
}

export type MarqueeGalleryProps = {
  items: readonly MarqueeGalleryItem[]
  title?: string
  eyebrow?: string
  description?: string
  rows?: 1 | 2
  speed?: number
  tone?: AccentTone
  className?: string
}

/** Galeria em faixas horizontais infinitas, com a segunda linha em sentido oposto. */
export function MarqueeGallery({
  items,
  title,
  eyebrow,
  description,
  rows = 2,
  speed = 40,
  tone = 'glow',
  className,
}: MarqueeGalleryProps) {
  const t = getAccentTone(tone)
  const half = Math.ceil(items.length / 2)
  const lines = rows === 2 && items.length > 3 ? [items.slice(0, half), items.slice(half)] : [items]

  return (
    <section className={cn('overflow-hidden py-14 lg:py-16', t.section, className)}>
      {title ? (
        <div className="container">
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            description={description}
            layout="split"
            className="mb-10"
          />
        </div>
      ) : null}

      <div className="space-y-4">
        {lines.map((line, lineIndex) => (
          <Marquee
            key={lineIndex}
            speed={speed}
            gap={16}
            direction={lineIndex % 2 === 0 ? 'left' : 'right'}
            ariaLabel={lineIndex === 0 ? 'Galeria de imagens' : undefined}
          >
            {line.map((item) => (
              <figure
                key={item.src + item.alt}
                className={cn(
                  'group relative h-56 w-72 shrink-0 overflow-hidden sm:h-64 sm:w-96',
                  tone === 'glow' ? 'rounded-2xl' : 'rounded-none',
                  t.panel,
                )}
              >
                <Image
                  src={item.src}
                  alt={item.alt}
                  fill
                  sizes="384px"
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                />
                {item.caption ? (
                  <figcaption className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/75 to-transparent p-4 text-sm font-semibold text-white">
                    {item.caption}
                  </figcaption>
                ) : null}
              </figure>
            ))}
          </Marquee>
        ))}
      </div>
    </section>
  )
}

'use client'

import { useRef, type ReactNode } from 'react'
import { useGSAP } from '@/lib/hooks/useGSAP'
import { prefersReducedMotion, useReducedMotion } from './useReducedMotion'

export type MarqueeProps = {
  children: ReactNode
  className?: string
  itemClassName?: string
  speed?: number
  direction?: 'left' | 'right'
  gap?: number
  pauseOnHover?: boolean
  ariaLabel?: string
}

export function Marquee({
  children,
  className,
  itemClassName,
  speed = 60,
  direction = 'left',
  gap = 32,
  pauseOnHover = true,
  ariaLabel,
}: MarqueeProps) {
  const root = useRef<HTMLDivElement>(null)
  const track = useRef<HTMLDivElement>(null)
  const firstSet = useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()

  useGSAP(
    ({ gsap }) => {
      const container = root.current
      const rail = track.current
      const set = firstSet.current
      if (!container || !rail || !set || reduced || prefersReducedMotion()) return

      let tween: gsap.core.Tween | undefined
      const build = (): void => {
        tween?.kill()
        gsap.set(rail, { x: 0 })

        const distance = set.getBoundingClientRect().width + gap
        if (distance <= 0) return

        tween = gsap.fromTo(
          rail,
          { x: direction === 'left' ? 0 : -distance },
          {
            x: direction === 'left' ? -distance : 0,
            duration: distance / Math.max(speed, 1),
            ease: 'none',
            repeat: -1,
          },
        )
      }

      const pause = (): void => {
        tween?.pause()
      }
      const resume = (): void => {
        tween?.resume()
      }
      const resizeObserver =
        typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(build)
      resizeObserver?.observe(set)
      window.addEventListener('resize', build)
      build()

      if (pauseOnHover) {
        container.addEventListener('pointerenter', pause)
        container.addEventListener('pointerleave', resume)
        container.addEventListener('focusin', pause)
        container.addEventListener('focusout', resume)
      }

      return () => {
        resizeObserver?.disconnect()
        window.removeEventListener('resize', build)
        container.removeEventListener('pointerenter', pause)
        container.removeEventListener('pointerleave', resume)
        container.removeEventListener('focusin', pause)
        container.removeEventListener('focusout', resume)
        tween?.kill()
      }
    },
    [direction, gap, pauseOnHover, reduced, speed],
    root,
  )

  const groupStyle = {
    display: 'flex',
    flex: 'none',
    gap,
  } as const

  return (
    <div ref={root} className={className} aria-label={ariaLabel} style={{ overflow: 'hidden' }}>
      <div
        ref={track}
        style={{ display: 'flex', gap, width: 'max-content', willChange: 'transform' }}
      >
        <div ref={firstSet} className={itemClassName} style={groupStyle}>
          {children}
        </div>
        <div
          ref={(node) => node?.setAttribute('inert', '')}
          aria-hidden="true"
          className={itemClassName}
          style={groupStyle}
        >
          {children}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

export function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && window.matchMedia(QUERY).matches
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const update = (): void => setReduced(media.matches)

    update()
    media.addEventListener('change', update)
    return () => media.removeEventListener('change', update)
  }, [])

  return reduced
}

import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

import { getAccentTone, type AccentTone } from './accentTones'

export type EyebrowHeadingProps = {
  title: ReactNode
  eyebrow?: ReactNode
  description?: ReactNode
  tone?: AccentTone
  align?: 'left' | 'center'
  layout?: 'stacked' | 'split'
  size?: 'md' | 'lg'
  titleAs?: 'h1' | 'h2' | 'h3'
  action?: ReactNode
  className?: string
}

const titleSizes = {
  md: 'text-3xl leading-[1.15] sm:text-4xl lg:text-[2.5rem]',
  lg: 'text-3xl leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
}

/** Cabeçalho de seção com linha de destaque, título temático e descrição opcional ao lado. */
export function EyebrowHeading({
  title,
  eyebrow,
  description,
  tone = 'glow',
  align = 'left',
  layout = 'stacked',
  size = 'md',
  titleAs: Title = 'h2',
  action,
  className,
}: EyebrowHeadingProps) {
  const t = getAccentTone(tone)
  const centered = align === 'center'
  const split = layout === 'split' && !centered

  const line = <span className={cn('h-px w-8 shrink-0', t.line)} aria-hidden />

  return (
    <div
      className={cn(
        split && 'flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between',
        centered && 'mx-auto max-w-3xl text-center',
        className,
      )}
    >
      <div className={cn(split ? 'max-w-2xl' : centered ? '' : 'max-w-3xl')}>
        {eyebrow ? (
          <div className={cn('mb-4 flex items-center gap-3', centered && 'justify-center')}>
            {line}
            <span
              className={cn('text-[0.65rem] font-medium uppercase tracking-[0.28em]', t.accent)}
            >
              {eyebrow}
            </span>
            {centered ? line : null}
          </div>
        ) : null}
        <Title className={cn(t.heading, titleSizes[size], centered && 'mx-auto')}>{title}</Title>
        {!split && description ? (
          <p
            className={cn(
              'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
              t.body,
              centered && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
        {!split && action ? (
          <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
            {action}
          </div>
        ) : null}
      </div>
      {split && (description || action) ? (
        <div className="max-w-md space-y-5">
          {description ? (
            <p className={cn('text-sm leading-relaxed lg:text-base', t.body)}>{description}</p>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  )
}

'use client'

import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { useEffect, type DependencyList, type RefObject } from 'react'

let registered = false

function ensureGsapPlugins(): void {
  if (typeof window === 'undefined' || registered) return
  gsap.registerPlugin(ScrollTrigger)
  registered = true
}

export type GSAPTools = {
  gsap: typeof gsap
  ScrollTrigger: typeof ScrollTrigger
}

export type GSAPCallback = (tools: GSAPTools) => void | (() => void)

export function useGSAP(
  callback: GSAPCallback,
  deps: DependencyList = [],
  scope?: RefObject<Element | null>,
): void {
  useEffect(() => {
    if (typeof window === 'undefined') return

    ensureGsapPlugins()

    let dispose: void | (() => void)
    const context = gsap.context(() => {
      dispose = callback({ gsap, ScrollTrigger })
    }, scope?.current ?? undefined)

    return () => {
      dispose?.()
      context.revert()
    }

    // Dependencies are deliberately controlled by each animation consumer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
